*** Add File: /var/folders/z_/1wgnkc556gg6ny5x122wt4z40000gn/T/opencode/week1-readonly-audit-20260919-current.mjs
+import { chromium } from '/var/folders/z_/1wgnkc556gg6ny5x122wt4z40000gn/T/opencode/lunch-generator-check/node_modules/playwright/index.mjs';
+
+const browser = await chromium.launch({ headless: true });
+const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
+const page = await context.newPage();
+const report = { browser: browser.version(), responses: [], failures: [], errors: [] };
+page.on('response', response => {
+    if (response.url().includes('cdnjs.cloudflare.com')) {
+        report.responses.push({ url: response.url(), status: response.status() });
+    }
+});
+page.on('requestfailed', request => report.failures.push({ url: request.url(), error: request.failure() }));
+page.on('pageerror', error => report.errors.push(error.message));
+
+async function snapshot() {
+    return page.evaluate(() => {
+        const icon = document.querySelector('.food-icon i');
+        const style = getComputedStyle(icon);
+        return {
+            name: document.querySelector('.food-name').textContent,
+            icon: icon.className,
+            before: getComputedStyle(icon, '::before').content,
+            font: style.fontFamily,
+            fontStatus: document.fonts.status,
+            width: icon.getBoundingClientRect().width,
+            height: icon.getBoundingClientRect().height,
+            buttonDisabled: document.getElementById('generateBtn').disabled,
+        };
+    });
+}
+
+try {
+    await page.goto('file:///Users/lizagill/ML_homework_lunch_generator/week1/index.html', { waitUntil: 'load' });
+    await page.waitForTimeout(700);
+    await page.evaluate(() => document.fonts.ready);
+    report.initial = await snapshot();
+    report.options = [];
+    for (let index = 0; index < 12; index++) {
+        await page.evaluate(index => { Math.random = () => (index + 0.1) / 12; }, index);
+        await page.getByRole('button', { name: 'Generate Lunch!' }).click();
+        await page.waitForTimeout(560);
+        await page.evaluate(() => document.fonts.ready);
+        report.options.push(await snapshot());
+        if (index === 7) {
+            await page.waitForTimeout(500);
+            await page.screenshot({ path: '/var/folders/z_/1wgnkc556gg6ny5x122wt4z40000gn/T/opencode/week1-audit-pasta-current.png', fullPage: true });
+        }
+    }
+
+    report.rapidClicks = await page.evaluate(async () => {
+        const name = document.querySelector('.food-name');
+        const display = document.querySelector('.lunch-display');
+        const button = document.getElementById('generateBtn');
+        const start = performance.now();
+        const events = [];
+        const observer = new MutationObserver(() => events.push({
+            at: Math.round(performance.now() - start),
+            name: name.textContent,
+            animationTime: display.getAnimations()[0]?.currentTime ?? null,
+        }));
+        observer.observe(name, { childList: true });
+        Math.random = () => 0.01;
+        button.click();
+        await new Promise(resolve => setTimeout(resolve, 200));
+        Math.random = () => 1.1 / 12;
+        button.click();
+        await new Promise(resolve => setTimeout(resolve, 1000));
+        observer.disconnect();
+        return events;
+    });
+
+    report.repeat = [];
+    await page.evaluate(() => { Math.random = () => 0.01; });
+    for (let index = 0; index < 2; index++) {
+        await page.getByRole('button', { name: 'Generate Lunch!' }).click();
+        await page.waitForTimeout(550);
+        report.repeat.push((await snapshot()).name);
+    }
+
+    await page.evaluate(() => { Math.random = () => 6.1 / 12; });
+    await page.getByRole('button', { name: 'Generate Lunch!' }).click();
+    await page.waitForTimeout(1100);
+    report.layout = [];
+    for (const width of [320, 360, 375, 390, 600, 768, 1280]) {
+        await page.setViewportSize({ width, height: 800 });
+        report.layout.push(await page.evaluate(() => {
+            const container = document.querySelector('.container');
+            const result = { width: innerWidth, documentWidth: document.documentElement.scrollWidth, overflow: [] };
+            for (const selector of ['h1', '.description', '.food-name', '.food-icon', '.generate-btn', '.footer']) {
+                const element = document.querySelector(selector);
+                const rect = element.getBoundingClientRect();
+                const parent = element.parentElement.getBoundingClientRect();
+                if (rect.left < parent.left - 1 || rect.right > parent.right + 1 || element.scrollWidth > element.clientWidth + 1) {
+                    result.overflow.push({ selector, left: rect.left, right: rect.right, clientWidth: element.clientWidth, scrollWidth: element.scrollWidth });
+                }
+            }
+            result.containerWidth = container.getBoundingClientRect().width;
+            return result;
+        }));
+        if (width === 320) {
+            await page.screenshot({ path: '/var/folders/z_/1wgnkc556gg6ny5x122wt4z40000gn/T/opencode/week1-audit-mobile-current.png', fullPage: true });
+        }
+    }
+
+    await page.evaluate(() => {
+        Math.random = () => 11.1 / 12;
+        document.getElementById('generateBtn').focus();
+    });
+    await page.keyboard.press('Enter');
+    await page.waitForTimeout(550);
+    report.keyboard = await snapshot();
+    report.accessibility = await page.evaluate(() => {
+        const button = document.getElementById('generateBtn');
+        const heading = document.querySelector('h1');
+        return {
+            liveRegions: document.querySelectorAll('[aria-live], [role="status"], [role="alert"]').length,
+            buttonColor: getComputedStyle(button).color,
+            buttonBackground: getComputedStyle(button).backgroundColor,
+            buttonFontSize: getComputedStyle(button).fontSize,
+            buttonFontWeight: getComputedStyle(button).fontWeight,
+            headingColor: getComputedStyle(heading).color,
+        };
+    });
+    console.log(JSON.stringify(report, null, 2));
+} finally {
+    await browser.close();
+}
*** End Patch

