+const metadataUrl = 'https://raw.githubusercontent.com/FortAwesome/Font-Awesome/6.4.0/metadata/icons.json';
+const metadataResponse = await fetch(metadataUrl);
+if (!metadataResponse.ok) throw new Error(`Metadata HTTP ${metadataResponse.status}`);
+const metadata = await metadataResponse.json();
+const options = [
+    { dish: 'Ramen', items: [['bowl-food', 'Миска с едой, без указания блюда'], ['utensils', 'Нейтральный значок еды']] },
+    { dish: 'Pasta', items: [['utensils', 'Нейтральный значок еды'], ['plate-wheat', 'Тарелка с колосьями; не паста']] },
+    { dish: 'Soup', items: [['bowl-food', 'Миска с едой, без указания блюда'], ['utensils', 'Нейтральный значок еды']] },
