+    { dish: 'Steak', items: [['utensils', 'Нейтральный значок еды'], ['fire', 'Огонь: ассоциация с жаркой / грилем']] },
+];
+const names = [...new Set(options.flatMap(row => row.items.map(([name]) => name)))];
+for (const name of names) {
+    if (!metadata[name]?.free.includes('solid')) throw new Error(`${name} is not free solid in 6.4.0`);
+}
+
